"OLAYLAR_EK2:1390-01-15:0":{"b": ["ازدواج یلدیرم بایزید با دسپینا خاتون", "4b10dc6c"], "d": ["رابطهٔ دست‌نشاندگی که پس از کوزوو با دسپوتات صربستان برقرار شد، با ازدواج اولیورا، دختر لازار، با بایزید مهر شد؛ نمونهٔ آشکار دیپلماسی ازدواج در دورهٔ آغازین.", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["تأسیس بیلربیگی آناتولی", "5ef8d3a7"], "d": ["برای اداره سرزمین‌های امارت‌های الحاق‌شده، بیلربیگی آناتولی سازمان یافت؛ نظام اداری دوبال روم‌ایلی-آناتولی کامل شد.", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["تکمیل مسجد اولو بورسا", "27bcc4a5"], "d": ["این مسجد جامع بیست‌گنبدی که با غنایم نیکوپولیس ساخته شد، نمونهٔ یادمانی معماری عثمانی آغازین و موزهٔ روباز هنر خوشنویسی است.", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["عزل و اعدام چاندارلی خلیل پاشا", "5e19438f"], "d": ["پس از فتح، صدراعظم از خاندان ریشه‌دار چاندارلی که از محاصره فاصله می‌گرفت اعدام شد؛ برای نخستین بار صدراعظمی به فرمان سلطان کشته می‌شد و عصر وزیران دوشیرمه‌تبار آغاز می‌گردید.", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["خراج‌گزار شدن مولداوی", "25bd3693"], "d": ["وویودنشین مولداوی پرداخت خراج را پذیرفت؛ کمربند سه‌گانهٔ دست‌نشاندگان در شمال دانوب با افلاق و ترانسیلوانیا، حائل شمالی امپراتوری شد. سایر آبادی‌هایی که در همین تاریخ پیوستند: یاش.", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["خراج دوبروونیک (راگوزا)", "d127c78a"], "d": ["جمهوری بازرگانان راگوزا در برابر خراج، خودمختاری و امتیازات تجاری‌اش را تضمین کرد؛ به‌عنوان دریچهٔ عثمانی به آدریاتیک ثروتمند شد. جزیرهٔ مله‌ت (Mljet) که خاک این جمهوری بود نیز در این وضعیت سهیم شد.", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["لشکرکشی افلاق: ولاد تپش", "fd4530bb"], "d": ["با لشکرکشی‌ای که علیه ولاد تپش، که از پرداخت خراج سر باز زده و فرستادگان را کشته بود، ترتیب یافت، افلاق دوباره به دست‌نشاندگی بازگردانده شد؛ حملهٔ شبانه و صحنه‌های هراس‌آور سیخ‌کشی در اروپا افسانه شد. سایر آبادی‌هایی که در همین تاریخ پیوستند: بخارست.", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["گشایش مجموعهٔ فاتح", "a150ea55"], "d": ["این مجموعه با هشت مدرسه‌اش (صحن ثمان) نخستین گام بزرگ در برنامهٔ تبدیل استانبول به مرکز دانش جهان اسلام بود.", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["علی قوشچی در استانبول", "8508229d"], "d": ["علی قوشچی، واپسین نمایندهٔ بزرگ رصدخانهٔ سمرقند، به دعوت فاتح در مدرسهٔ ایاصوفیه مدرس شد؛ سنت ریاضیات و نجوم را در استانبول بنیان نهاد.", "fd325f60"]},
